34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "postcode")
56	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
57	    private String postcode;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    private String email;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "identity_key")
80	    private String identityKey;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "household_member_count")
86	    private Integer householdMemberCount;
87	
88	    @Column(name = "membership_number")
89	    private String membershipNumber;
90	
91	    @Column(name = "possible_duplicate")
92	    private Boolean possibleDuplicate;
93	
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    @Column(name = "deleted", nullable = false)
98	    private boolean deleted;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getTitle() {
104	        return this.title;
105	    }
106	
107	    public void setTitle(String title) {
108	        this.title = title;
109	    }
110	
111	    /**
112	     * The owner's salutation, derived on read: the {@link #getTitle() title} and last name separated
113	     * by a single space (e.g. {@code "DR who"}) when a title is present, or just the last name when no
114	     * title was supplied.
115	     */
116	    @Transient
117	    public String getSalutation() {
118	        if (this.title != null && !this.title.isBlank()) {
119	            return this.title + " " + getLastName();
120	        }
121	        return getLastName();
122	    }
123	
124	    public String getAddress() {
125	        return this.address;
126	    }
127	
128	    public void setAddress(String address) {
129	        this.address = address;
130	    }
131	
132	    public String getAddressLine1() {
133	        return this.addressLine1;
134	    }
135	
136	    public void setAddressLine1(String addressLine1) {
137	        this.addressLine1 = addressLine1;
138	    }
139	
140	    public String getAddressLine2() {
141	        return this.addressLine2;
142	    }
143	
144	    public void setAddressLine2(String addressLine2) {
145	        this.addressLine2 = addressLine2;
146	    }
147	
148	    public String getCity() {
149	        return this.city;
150	    }
151	
152	    public void setCity(String city) {
153	        this.city = city;
154	    }
155	
156	    public String getPostcode() {
157	        return this.postcode;
158	    }
159	
160	    public void setPostcode(String postcode) {
161	        this.postcode = postcode;
162	    }
163	
164	    public String getTelephone() {
165	        return this.telephone;
166	    }
167	
168	    public void setTelephone(String telephone) {
169	        this.telephone = telephone;
170	    }
171	
172	    public String getEmail() {
173	        return this.email;
174	    }
175	
176	    public void setEmail(String email) {
177	        this.email = email;
178	    }
179	
180	    public LocalDate getRegistrationDate() {
181	        return this.registrationDate;
182	    }
183	
184	    public void setRegistrationDate(LocalDate registrationDate) {
185	        this.registrationDate = registrationDate;
186	    }
187	
188	    public LocalDate getBirthDate() {
189	        return this.birthDate;
190	    }
191	
192	    public void setBirthDate(LocalDate birthDate) {
193	        this.birthDate = birthDate;
194	    }
