196	    public String getCustomerCode() {
197	        return this.customerCode;
198	    }
199	
200	    public void setCustomerCode(String customerCode) {
201	        this.customerCode = customerCode;
202	    }
203	
204	    public String getHouseholdId() {
205	        return this.householdId;
206	    }
207	
208	    public void setHouseholdId(String householdId) {
209	        this.householdId = householdId;
210	    }
