220	    public Integer getNamesakeCount() {
221	        return this.namesakeCount;
222	    }
223	
224	    public void setNamesakeCount(Integer namesakeCount) {
225	        this.namesakeCount = namesakeCount;
226	    }
227	
228	    public Integer getHouseholdMemberCount() {
229	        return this.householdMemberCount;
230	    }
231	
232	    public void setHouseholdMemberCount(Integer householdMemberCount) {
233	        this.householdMemberCount = householdMemberCount;
234	    }
235	
236	    public String getMembershipNumber() {
237	        return this.membershipNumber;
238	    }
239	
240	    public void setMembershipNumber(String membershipNumber) {
241	        this.membershipNumber = membershipNumber;
242	    }
243	
244	    public Boolean getPossibleDuplicate() {
245	        return this.possibleDuplicate;
246	    }
247	
248	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
249	        this.possibleDuplicate = possibleDuplicate;
250	    }
251	
252	    public Integer getPossibleDuplicateOf() {
253	        return this.possibleDuplicateOf;
254	    }
255	
256	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
257	        this.possibleDuplicateOf = possibleDuplicateOf;
258	    }
259	
260	    /**
261	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; the delete
262	     * endpoint flags this true and retains the row rather than removing it. Deleted owners are
263	     * ignored by the create endpoint's duplicate and identity checks.
264	     */
265	    public boolean isDeleted() {
266	        return this.deleted;
267	    }
268	
269	    public void setDeleted(boolean deleted) {
270	        this.deleted = deleted;
271	    }
272	
273	    /**
274	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
275	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
276	     * ({@link #householdMemberCount}), and add 3 for tenure over 365 days (whole days from
277	     * {@link #registrationDate} to today).
278	     */
279	    @Transient
280	    public Integer getMembershipPoints() {
281	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
282	            this.registrationDate);
283	    }
284	
285	    /**
286	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
287	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
288	     */
289	    @Transient
290	    public Integer getMembershipLevel() {
291	        return membershipLevel(getMembershipPoints());
292	    }
293	
294	    /** The membership points derived from the given factors: they start at 0, add 2 when
295	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
296	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
297	     *  {@link #hasTenureBonus(LocalDate)}). */
298	    private static int membershipPoints(String email, Integer namesakeCount,
299	            Integer householdMemberCount, LocalDate registrationDate) {
300	        int points = 0;
301	        if (email != null && !email.isBlank()) {
302	            points += 2;
303	        }
304	        if (namesakeCount != null && namesakeCount == 0) {
305	            points += 1;
306	        }
307	        if (householdMemberCount != null && householdMemberCount >= 3) {
308	            points += 2;
309	        }
310	        if (hasTenureBonus(registrationDate)) {
311	            points += 3;
312	        }
313	        return points;
314	    }
315	
316	    /** Whether the owner's tenure earns the membership tenure bonus: the whole days from
317	     *  {@code registrationDate} to today exceed 365. A null registration date earns no bonus. */
318	    private static boolean hasTenureBonus(LocalDate registrationDate) {
319	        return registrationDate != null
320	            && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
321	    }
322	
323	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
324	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
325	    private static int membershipLevel(int points) {
326	        if (points >= 6) {
327	            return 4;
328	        }
329	        if (points >= 4) {
330	            return 3;
331	        }
332	        if (points >= 2) {
333	            return 2;
334	        }
335	        return 1;
336	    }
337	
338	    /**
339	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
340	     * present, otherwise {@code "PHONE"}.
341	     */
342	    @Transient
343	    public String getContactPreference() {
344	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
345	    }
346	
347	    /**
348	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
349	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
350	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
351	     * date to measure against) is available.
352	     */
353	    @Transient
354	    public String getAgeBand() {
355	        if (this.birthDate == null || this.registrationDate == null) {
356	            return null;
357	        }
358	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
359	        if (age < 18) {
360	            return "MINOR";
361	        }
362	        if (age < 65) {
363	            return "ADULT";
364	        }
365	        return "SENIOR";
366	    }
367	
368	    /**
369	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
370	     * {@link #customerCode}, derived on read.
371	     */
372	    @Transient
373	    public Integer getCheckDigit() {
374	        return luhnCheckDigit(this.customerCode);
375	    }
376	
377	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
378	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
379	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
380	        "NSW", new int[] {2000, 2099},
381	        "VIC", new int[] {3000, 3099},
382	        "QLD", new int[] {4000, 4099});
383	
384	    /**
385	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
386	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
387	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
388	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
389	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
390	     */
391	    @Transient
392	    public String getRegion() {
393	        String byPostcode = regionForPostcode(this.postcode);
394	        if (byPostcode != null) {
395	            return byPostcode;
396	        }
397	        if ("Sydney".equals(this.city)) {
398	            return "NSW";
399	        }
400	        if ("Melbourne".equals(this.city)) {
401	            return "VIC";
402	        }
403	        if ("Brisbane".equals(this.city)) {
404	            return "QLD";
405	        }
406	        return "UNKNOWN";
407	    }
408	
409	    /**
410	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
411	     * customer code}: the region segment before the first '-' of the customer code
412	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
413	     * code has been assigned yet.
414	     */
415	    @Transient
416	    public String getLocality() {
417	        if (this.customerCode != null) {
418	            int dash = this.customerCode.indexOf('-');
419	            if (dash > 0) {
420	                return this.customerCode.substring(0, dash);
421	            }
422	        }
423	        return getRegion();
424	    }
425	
426	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
427	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
428	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
429	        "NSW", "Australia/Sydney",
430	        "VIC", "Australia/Melbourne",
431	        "QLD", "Australia/Brisbane");
432	
433	    /**
434	     * The owner's timezone, derived on read as the IANA name for the owner's
435	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
436	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
437	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
438	     * the table (e.g. {@code UNKNOWN}).
439	     */
440	    @Transient
441	    public String getTimezone() {
442	        return timezoneForRegion(getLocality());
443	    }
444	
445	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
446	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
447	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
448	    public static String timezoneForRegion(String region) {
449	        return REGION_TIMEZONES.get(region);
450	    }
451	
452	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
453	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
454	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
455	    public static int[] postcodeRangeForRegion(String region) {
456	        return REGION_POSTCODE_RANGES.get(region);
457	    }
458	
459	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
460	     *  absent, not a 4-digit value, or in no known range. */
461	    private static String regionForPostcode(String postcode) {
462	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
463	            return null;
464	        }
465	        int value = Integer.parseInt(postcode);
466	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
467	            int[] range = entry.getValue();
468	            if (value >= range[0] && value <= range[1]) {
469	                return entry.getKey();
470	            }
471	        }
472	        return null;
473	    }
474	
475	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
476	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
477	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
478	     *  {@code +1}), so a number matches at most one. */
479	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
480	        "+61", 9, "+1", 10);
481	
482	    /**
483	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
484	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
485	     * to the raw value when it is {@code null} or begins with no recognised country code.
486	     */
487	    @Transient
488	    public String getTelephoneDisplay() {
489	        if (this.telephone == null) {
490	            return null;
491	        }
492	        String countryCode = countryCodeOf(this.telephone);
493	        if (countryCode == null) {
494	            return this.telephone;
495	        }
496	        String national = this.telephone.substring(countryCode.length());
497	        StringBuilder grouped = new StringBuilder(countryCode);
498	        for (int i = 0; i < national.length(); i++) {
499	            if (i % 3 == 0) {
500	                grouped.append(' ');
501	            }
502	            grouped.append(national.charAt(i));
503	        }
504	        return grouped.toString();
505	    }
506	
507	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
508	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
509	    public static String countryCodeOf(String telephone) {
510	        if (telephone == null) {
511	            return null;
512	        }
513	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
514	            if (telephone.startsWith(countryCode)) {
515	                return countryCode;
516	            }
517	        }
518	        return null;
519	    }
520	
521	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
522	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
523	     *  {@code +1 => 10}). */
524	    public static Integer nationalNumberLength(String countryCode) {
525	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
526	    }
527	
528	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
529	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
530	     *  digit-free value yields {@code 0}. */
531	    private static int luhnCheckDigit(String value) {
532	        int sum = 0;
533	        boolean doubling = true;
534	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
535	            char c = value.charAt(i);
536	            if (c < '0' || c > '9') {
537	                continue;
538	            }
539	            int digit = c - '0';
540	            if (doubling) {
541	                digit *= 2;
542	                if (digit > 9) {
543	                    digit -= 9;
544	                }
545	            }
546	            sum += digit;
547	            doubling = !doubling;
548	        }
549	        return (10 - (sum % 10)) % 10;
550	    }
551	
552	    protected Set<Pet> getPetsInternal() {
553	        if (this.pets == null) {
554	            this.pets = new HashSet<>();
555	        }
556	        return this.pets;
557	    }
558	
559	    protected void setPetsInternal(Set<Pet> pets) {
560	        this.pets = pets;
561	    }
562	
563	    public List<Pet> getPets() {
564	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
565	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
566	        return Collections.unmodifiableList(sortedPets);
567	    }
568	
569	    public void setPets(List<Pet> pets) {
570	        this.pets = new HashSet<>(pets);
571	    }
572	
573	    public void addPet(Pet pet) {
574	        getPetsInternal().add(pet);
575	        pet.setOwner(this);
576	    }
577	
578	    /**
579	     * Return the Pet with the given name, or null if none found for this Owner.
580	     *
581	     * @param name to test
582	     * @return true if pet name is already in use
583	     */
584	    public Pet getPet(String name) {
585	        return getPet(name, false);
586	    }
587	
588	    /**
589	     * Return the Pet with the given name, or null if none found for this Owner.
590	     *
591	     * @param name to test
592	     * @return true if pet name is already in use
593	     */
594	    public Pet getPet(String name, boolean ignoreNew) {
595	        name = name.toLowerCase();
596	        for (Pet pet : getPetsInternal()) {
597	            if (!ignoreNew || !pet.isNew()) {
598	                String compName = pet.getName();
599	                compName = compName.toLowerCase();
600	                if (compName.equals(name)) {
601	                    return pet;
602	                }
603	            }
604	        }
605	        return null;
606	    }
607	
608	    public Pet getPet(Integer petId) {
609	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
610	    }
611	
612	    @Override
613	    public String toString() {
614	        return new ToStringCreator(this)
615	
616	            .append("id", this.getId())
617	            .append("new", this.isNew())
618	            .append("lastName", this.getLastName())
619	            .append("firstName", this.getFirstName())
620	            .append("address", this.address)
621	            .append("city", this.city)
622	            .append("telephone", this.telephone)
623	            .toString();
624	    }
625	}
