203	    /**
204	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
205	     * returning whether the owner may proceed to creation. The structured fields are preferred when
206	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
207	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
208	     * composed value (the normalized addressLine1, with a single space and the normalized
209	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
210	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
211	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
212	     * address. This is the single place the owner's address is read, canonicalized and written back,
213	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
214	     */
215	    private boolean normalizeAddressFields(Owner owner) {
216	        String line1 = normalizeAddress(owner.getAddressLine1());
217	        if (!line1.isEmpty()) {
218	            String line2 = normalizeAddress(owner.getAddressLine2());
219	            owner.setAddressLine1(line1);
220	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
221	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
222	            return true;
223	        }
224	        String address = normalizeAddress(owner.getAddress());
225	        if (address.isEmpty()) {
226	            return false;
227	        }
228	        owner.setAddress(address);
229	        return true;
230	    }
