537	    /**
538	     * The number of existing owners registered in {@code city}, compared case-insensitively
539	     * with collapsed whitespace.
540	     */
541	    private int countOwnersInCity(String city) {
542	        String normalized = normalizeHouseholdField(city);
543	        return (int) this.clinicService.findAllOwners().stream()
