601	    /**
602	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
603	     * last name, compared case-insensitively.
604	     */
605	    private int countNamesakes(Owner owner) {
606	        String firstName = normalizeHouseholdField(owner.getFirstName());
607	        String lastName = normalizeHouseholdField(owner.getLastName());
608	        return (int) this.clinicService.findAllOwners().stream()
609	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
610	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
611	            .count();
612	    }
