614	    /**
615	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
616	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
617	     * unusually high daily signup volume.
618	     */
619	    private boolean isBulkSignupWarning() {
620	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
621	    }
