623	    /** The number of existing owners whose registration date is {@code date}. */
624	    private int countOwnersRegisteredOn(LocalDate date) {
625	        return (int) this.clinicService.findAllOwners().stream()
626	            .filter(existing -> date.equals(existing.getRegistrationDate()))
627	            .count();
628	    }
