630	    /**
631	     * The single derived key all duplicate detection flows through, formed from the owner's
632	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
633	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
634	     * id is derived, so the household segment is empty at that point. Because the telephone is part
635	     * of the key, two owners in the same household with different telephones resolve to different
636	     * keys and are both allowed.
637	     */
638	    private static String identityKey(Owner owner) {
639	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
640	        String email = owner.getEmail() == null ? "" : owner.getEmail();
641	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
642	        return telephone + "|" + email + "|" + household;
643	    }
644	
645	    /**
646	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
647	     * duplicate condition: the previously separate telephone, email and household checks are now all
648	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
649	     * trips it is rejected with {@code 409 CONFLICT}.
650	     */
651	    private boolean isDuplicate(Owner owner) {
652	        String key = owner.getIdentityKey();
653	        return this.clinicService.findAllOwners().stream()
654	            .filter(existing -> !existing.isDeleted())
655	            .map(Owner::getIdentityKey)
656	            .filter(existing -> existing != null)
657	            .anyMatch(key::equals);
658	    }
