660	    /** Common street-type abbreviations expanded during address normalization. */
661	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
662	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
663	
664	    /**
665	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
666	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
667	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
668	     * string when {@code address} is null or blank after normalization.
669	     */
670	    private static String normalizeAddress(String address) {
671	        if (address == null) {
672	            return "";
673	        }
674	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
675	        if (collapsed.isEmpty()) {
676	            return "";
677	        }
678	        StringBuilder sb = new StringBuilder(collapsed.length());
679	        for (String token : collapsed.split(" ")) {
680	            if (sb.length() > 0) {
681	                sb.append(' ');
682	            }
683	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
684	        }
685	        return sb.toString();
686	    }
687	
688	    /**
689	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
690	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
691	     */
692	    private static String normalizeHouseholdField(String value) {
693	        if (value == null) {
694	            return "";
695	        }
696	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
697	    }
698	
699	    /**
700	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
701	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
702	     * key rather than re-derived from the underlying fields here, so the household is described in one
703	     * place and every household-keyed value stays consistent with it.
704	     */
705	    private List<Owner> findHousemates(Owner owner) {
706	        String householdId = householdId(owner);
707	        return this.clinicService.findAllOwners().stream()
708	            .filter(existing -> !existing.isDeleted())
709	            .filter(existing -> householdId(existing).equals(householdId))
710	            .toList();
711	    }
712	
713	    /**
714	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
715	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
716	     */
717	    private int countHouseholdMembers(Owner owner) {
718	        return findHousemates(owner).size() + 1;
719	    }
720	
721	    /**
722	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
723	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
724	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
725	     * string standing in for a missing postcode), so housemates always resolve to the same value
726	     * regardless of registration order, and owners sharing a last name and postcode share it
727	     * automatically.
728	     */
729	    private static String householdId(Owner owner) {
730	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
731	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
732	        return sha256Hex(key).substring(0, 12);
733	    }
734	
735	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
736	    private static String sha256Hex(String input) {
737	        try {
738	            byte[] digest = MessageDigest.getInstance("SHA-256")
739	                .digest(input.getBytes(StandardCharsets.UTF_8));
740	            StringBuilder sb = new StringBuilder(digest.length * 2);
741	            for (byte b : digest) {
742	                sb.append(String.format("%02X", b));
743	            }
744	            return sb.toString();
745	        }
746	        catch (NoSuchAlgorithmException e) {
747	            throw new IllegalStateException("SHA-256 not available", e);
748	        }
749	    }
750	}
